```python
import sys


def main():
    data = sys.stdin.read().split()
    if not data:
        return
    pos = 0
    k = int(data[pos]); pos += 1
    prog = []
    for _ in range(k):
        op = data[pos].upper(); pos += 1
        if op in ("PUSH", "JNZ"):
            arg = int(data[pos]); pos += 1
            prog.append((op, arg))
        else:
            prog.append((op, None))

    out = []
    stack = []
    pc = 0
    steps = 0
    while True:
        if steps >= 10000:
            print("ERR")
            return
        if pc < 0 or pc >= len(prog):
            print("ERR")
            return
        op, arg = prog[pc]
        steps += 1
        if op == "PUSH":
            stack.append(arg)
        elif op == "POP":
            if not stack:
                print("ERR"); return
            stack.pop()
        elif op == "DUP":
            if not stack:
                print("ERR"); return
            stack.append(stack[-1])
        elif op == "SWAP":
            if len(stack) < 2:
                print("ERR"); return
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op in ("ADD", "SUB", "MUL"):
            if len(stack) < 2:
                print("ERR"); return
            a = stack.pop()
            b = stack.pop()
            if op == "ADD":
                stack.append(b + a)
            elif op == "SUB":
                stack.append(b - a)
            else:
                stack.append(b * a)
        elif op == "PRINT":
            if not stack:
                print("ERR"); return
            out.append(str(stack.pop()))
        elif op == "JNZ":
            if not stack:
                print("ERR"); return
            v = stack.pop()
            if v != 0:
                pc = arg
                continue
        elif op == "HALT":
            sys.stdout.write("\n".join(out) + ("\n" if out else ""))
            return
        else:
            print("ERR")
            return
        pc += 1


main()
```

Two public cases verified: first prints `0`, second prints `ERR`. Notes: `SUB`/`MUL` compute `b - a` / `b * a`; all errors (underflow, out-of-range jump, 10000-step limit, running past the last instruction, unknown opcode) produce a single `ERR` line.
